const xml = $input.first().json.data;

// Split into article blocks so each title stays paired with its own abstract
const articles = xml.split('<PubmedArticle>').slice(1);
const strip = s => s ? s.replace(/<[^>]+>/g, '').trim() : '';

const papers = articles.map(block => {
  const titleMatch = block.match(/<ArticleTitle[^>]*>([\s\S]*?)<\/ArticleTitle>/);
  const abstractParts = [...block.matchAll(/<AbstractText[^>]*>([\s\S]*?)<\/AbstractText>/g)].map(m => m[1]);
  return {
    title: strip(titleMatch ? titleMatch[1] : 'No title'),
    abstract: abstractParts.length ? strip(abstractParts.join(' ')) : 'No abstract available',
    source: 'PubMed'
  };
});

return papers.map(p => ({ json: p }));

