const keywords = ['retinal', 'diagnostic', 'imaging', 'ophthalmology', 'clinical', 'biomarker', 'cancer', 'EEG', 'neural', 'medical', 'drug', 'disease', 'patient', 'therapy', 'genomics'];

const categoryToLabType = {
  'neuroscience': 'Genomics',
  'biophysics': 'Genomics', 
  'genomics': 'Genomics',
  'biochemistry': 'Pharma',
  'microbiology': 'Pharma',
  'pharmacology': 'Pharma',
  'developmental biology': 'Biotech',
  'physiology': 'Biotech',
  'cell biology': 'Biotech',
  'diagnostic': 'Diagnostics',
  'clinical': 'Diagnostics',
  'pathology': 'Diagnostics'
};

function getLabType(item) {
  const category = (item.json.category || '').toLowerCase();
  const text = (item.json.title + ' ' + (item.json.abstract || '')).toLowerCase();

  for (const [key, labType] of Object.entries(categoryToLabType)) {
    if (category.includes(key) || text.includes(key)) {
      return labType;
    }
  }
  return 'Biotech';
}

return $input.all().filter(item => {
  const text = (item.json.title + ' ' + (item.json.abstract || '') + ' ' + (item.json.category || '')).toLowerCase();
  return keywords.some(kw => text.includes(kw));
}).map(item => ({ 
  json: {
    ...item.json,
    lab_type: getLabType(item),
    last_digest_sent: new Date().toISOString().split('T')[0]
  }
}));

const papers = $('Code in JavaScript2').all();
const summaries = $('HTTP Request3').all();

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const blocks = papers.map((p, i) => {
  const title = esc(p.json.title || 'No title');
  const source = esc(p.json.source || 'Unknown');
  const choices = summaries[i] && summaries[i].json && summaries[i].json.choices;
  const summary = (choices && choices[0] && choices[0].message && choices[0].message.content)
    ? esc(choices[0].message.content)
    : 'No summary available';
  return '<div style="margin-bottom:20px;">'
    + '<h3 style="margin:0 0 4px 0;">' + (i + 1) + '. ' + title + '</h3>'
    + '<div style="color:#666;font-size:12px;margin-bottom:6px;">Source: ' + source + '</div>'
    + '<div>' + summary + '</div>'
    + '</div>';
});

const html = '<div style="font-family:Arial,sans-serif;line-height:1.5;">'
  + '<h2>Research Digest — ' + papers.length + ' papers</h2>'
  + blocks.join('')
  + '</div>';

return [{ json: { html, count: papers.length } }];

